-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.quiz_rounds (
  id uuid not null,
  user_id uuid default auth.uid() not null,
  quiz_id text not null,
  section_id text not null,
  origin text not null,
  question_count integer not null,
  shuffled boolean not null,
  shuffle_options boolean not null,
  answered integer default 0 not null,
  correct integer default 0 not null,
  status text default 'active'::text not null,
  started_at timestamp with time zone not null,
  finished_at timestamp with time zone,
  updated_at timestamp with time zone default now() not null,
  constraint quiz_rounds_pkey PRIMARY KEY (user_id, id),
  constraint quiz_rounds_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint quiz_rounds_answered_check CHECK ((answered >= 0)),
  constraint quiz_rounds_check CHECK (((correct >= 0) AND (correct <= answered))),
  constraint quiz_rounds_check1 CHECK (((status = 'finished'::text) = (finished_at IS NOT NULL))),
  constraint quiz_rounds_origin_check CHECK ((origin = ANY (ARRAY['cover'::text, 'restart'::text, 'repeat_all'::text, 'repeat_wrong'::text]))),
  constraint quiz_rounds_question_count_check CHECK (((question_count >= 1) AND (question_count <= 10000))),
  constraint quiz_rounds_quiz_id_check CHECK ((quiz_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
  constraint quiz_rounds_section_id_check CHECK ((section_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
  constraint quiz_rounds_status_check CHECK ((status = ANY (ARRAY['active'::text, 'finished'::text, 'abandoned'::text])))
);

CREATE INDEX quiz_rounds_finished ON public.quiz_rounds USING btree (finished_at) WHERE (finished_at IS NOT NULL);
CREATE INDEX quiz_rounds_recent ON public.quiz_rounds USING btree (user_id, quiz_id, started_at DESC);
CREATE INDEX quiz_rounds_started ON public.quiz_rounds USING btree (started_at);

CREATE TRIGGER quota_rows AFTER INSERT ON public.quiz_rounds FOR EACH ROW EXECUTE FUNCTION public.quota_rows('20000');

alter table public.quiz_rounds enable row level security;

create policy "own quiz rounds" on public.quiz_rounds
  as permissive
  for all
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)))
  with check (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant delete, select on table public.quiz_rounds to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.quiz_rounds to service_role;
